        "line": "p2:L6"
      }
    ],
    "p_statements": [
      {
        "code": "P201",
        "type": "예방",
        "text": "사용 전 취급 설명서를 확보하시오.",
        "line": "p2:L9"
      },
      {
        "code": "P202",
        "type": "예방",
        "text": "모든 안전 예방조치 문구를 읽고 이해하기 전에는 취급하지 마시오.",
        "line": "p2:L10"
      },
      {
        "code": "P210",
        "type": "예방",
        "text": "열·스파크·화염·고열로부터 멀리하시오 - 금연",
        "line": "p2:L11"
      },
      {
        "code": "P261",
        "type": "예방",
        "text": "가스·미스트·증기·스프레이의 흡입을 피하시오.",
        "line": "p2:L12"
      },
      {
        "code": "P271",
        "type": "예방",
        "text": "옥외 또는 환기가 잘 되는 곳에서만 취급하시오.",
        "line": "p2:L13"
      },
      {
        "code": "P280",
        "type": "예방",
        "text": "보호장갑·보호의·보안경·안면보호구를 착용하시오.",
        "line": "p2:L14"
      },
      {
        "code": "P304+P340",
        "type": "대응",
        "text": "흡입하면 신선한 공기가 있는 곳으로 옮기고 호흡하기 쉬운 자세로 안정을 취하시오.",
        "line": "p2:L16"
      },
      {
        "code": "P308+P313",
        "type": "대응",
        "text": "노출되거나 노출이 우려되면 의학적인 조치·조언을 구하시오.",
        "line": "p2:L17"
      },
      {
        "code": "P312",
        "type": "대응",
        "text": "불편함을 느끼면 의료기관(의사)의 진찰을 받으시오.",
        "line": "p2:L18"
      },
      {
        "code": "P377",
        "type": "대응",
        "text": "누출성 가스 화재 시 누출을 안전하게 막을 수 없다면 불을 끄려하지 마시오.",
        "line": "p2:L19"
      },
      {
        "code": "P381",
        "type": "대응",
        "text": "안전하게 처리하는 것이 가능하면 모든 점화원을 제거하시오.",
        "line": "p2:L20"
      },
      {
        "code": "P403",
        "type": "저장",
        "text": "환기가 잘 되는 곳에 보관하시오.",
        "line": "p2:L22"
      },
      {
        "code": "P403+P233",
        "type": "저장",
        "text": "용기는 환기가 잘 되는 곳에 단단히 밀폐하여 저장하시오.",
        "line": "p2:L23"
      },
      {
        "code": "P405",
        "type": "저장",
        "text": "잠금장치가 있는 저장장소에 저장하시오.",
        "line": "p2:L24"
      },
      {
        "code": "P410+P403",
        "type": "저장",
        "text": "직사광선을 피하고 환기가 잘 되는 곳에 보관하시오.",
        "line": "p2:L25"
      },
      {
        "code": "P501",
        "type": "폐기",
        "text": "(관련 법규에 명시된 내용에 따라) 내용물과 용기를 폐기하시오",
        "line": "p2:L27"
      }
